  "Hunger can rise by 100 to 200 kcal. A bigger protein snack helps, and about 150 kcal extra is fine this week. Drink a bit more water. Water weight of 0.5 to 2 kg is normal.": "الجوع ممكن يزيد 100 إلى 200 سعرة. سناك فيه بروتين أكثر يساعد، وحوالي 150 سعرة زيادة عادي هالأسبوع. اشرب ماي أكثر شوي. وزن الماي من 0.5 إلى 2 كجم طبيعي.",
  "Hunger can rise by 100 to 200 kcal. A bigger protein snack helps. Water weight of 0.5 to 2 kg is normal.": "الجوع ممكن يزيد 100 إلى 200 سعرة. وجبة خفيفة بروتين أكبر تساعد. وزن موية 0.5 إلى 2 كجم طبيعي.",
