  "You slept {n} h. Aim for 7.5 to 8 h: lights out a bit earlier and no screens 30 minutes before.": "نمت {n} ساعة. حاول 7.5 إلى 8 ساعات: نام أبكر شوية وبدون شاشات قبل النوم بـ 30 دقيقة.",
  "You specialize in": "تخصصك في",
  "You still need {n} g of protein today. Protein helps you keep muscle, so try to fit some into your free meal.": "باقي لك {n} جم بروتين اليوم. البروتين يساعدك تحافظ على العضل، فحاول تدخل شوية منه في وجبتك الحرة.",
  "You still need {n} g of protein. A cup of Greek yogurt after training covers most of it.": "باقي لك {n} جم بروتين. كوب زبادي يوناني بعد التمرين يغطي أغلبه.",
