  "Your coach manages this workout.": "مدربك هو اللي يدير هالتمرين.",
  "Your coach sees your food, workouts, weight and sleep. Cycle data and health tests stay private.": "مدربك يشوف أكلك وتمارينك ووزنك ونومك. بيانات الدورة والتحاليل تبقى خاصة.",
