  "Your coach will see your food, workouts, weight and sleep so they can guide you. Cycle data stays private.": "مدربك بيشوف أكلك وتمارينك ووزنك ونومك عشان يوجهك. بيانات الدورة تبقى خاصة.",
  "Your coach, online": "مدربك، أونلاين",
  "Your coaching": "تدريبك",
