  "Your cycle has 4 phases: your period, the follicular phase (energy rises), ovulation (an egg is released), and the luteal phase (progesterone rises, hunger and water weight can go up). A normal cycle is 21 to 35 days.": "دورتك لها 4 مراحل: أيام النزول، المرحلة الجريبية (الطاقة تزيد)، التبويض (تنطلق بويضة)، والمرحلة الأصفرية (البروجسترون يزيد، والجوع ووزن الموية ممكن يزيدون). الدورة الطبيعية من 21 إلى 35 يوم.",
