  "These meals give about {a} g protein of your {b} g. Add {n} g more: a protein snack, or a bigger portion of chicken, meat or fish.": "هالوجبات تعطيك حوالي {a} جم بروتين من {b} جم. زيد {n} جم: سناك بروتين، أو حصة أكبر من الدجاج أو اللحم أو السمك.",
  "Left out {x}. The rest is bigger, and this meal is now about {n} kcal.": "شلت {x}. الباقي صار أكثر، والوجبة صارت تقريبًا {n} سعرة.",
