  "Step {n}": "الخطوة {n}",
  "Add a step": "أضف خطوة",
  "You’ve used {w} kg for {n} workouts in a row. Time to go up: start at {w2} kg.": "صار لك {n} تمارين ورا بعض على {w} كجم. وقت الزيادة: ابدأ بـ {w2} كجم.",
  "Last time every set hit {hi} reps at {w} kg. Start at {w2} kg today.": "آخر مرة كل الجولات وصلت {hi} عدة بـ {w} كجم. ابدأ اليوم بـ {w2} كجم.",
  "Last time {w} kg was heavy ({r} reps). Start at {w2} kg to get {lo} or more.": "آخر مرة {w} كجم كان ثقيل ({r} عدات). ابدأ بـ {w2} كجم عشان توصل {lo} أو أكثر.",
  "Every set hit {hi} reps. Next time start at {w2} kg.": "كل الجولات وصلت {hi} عدة. المرة الجاية ابدأ بـ {w2} كجم.",
  "That’s {n} workouts at {w} kg. Next time go to {w2} kg, even if you get fewer reps.": "هذا التمرين رقم {n} على {w} كجم. المرة الجاية زِد لـ {w2} كجم، حتى لو العدات قلّت.",
  "Done. Top set {w} kg × {r}. Stay at {w} kg until every set gets {hi}.": "خلصت. أقوى جولة {w} كجم × {r}. خلك على {w} كجم لين كل الجولات توصل {hi}.",
  "Done. Next time start at {w2} kg so you can do {lo}–{hi} reps.": "خلصت. المرة الجاية ابدأ بـ {w2} كجم عشان تقدر تسوي {lo}–{hi} عدة.",
  "Your reps are dropping ({a} → {b}), so you’re tired. Rest 2–3 minutes and stay at {w} kg.": "عداتك تنزل ({a} ← {b})، يعني تعبت. ارتاح 2–3 دقايق وخلك على {w} كجم.",
  "Strong and steady. Last set: go heavier, {w2} kg for {a}–{b} reps.": "قوي وثابت يا وحش. آخر جولة ثقّل: {w2} كجم لـ {a}–{b} عدات.",
  "{r} reps is light for {lo}–{hi}. Go to {w2} kg next set.": "{r} عدة خفيف على {lo}–{hi}. الجولة الجاية {w2} كجم.",
  "Top of the range. Try {w2} kg next set.": "وصلت أعلى النطاق. جرّب {w2} كجم الجولة الجاية.",
  "Good jump to {w} kg, {r} reps is in the range. Stay here.": "زيادة حلوة لـ {w} كجم، و{r} عدات داخل النطاق. خلك هنا.",
  "Close to {lo}. Stay at {w} kg and rest a little longer.": "قريب من {lo}. خلك على {w} كجم وارتاح شوي أكثر.",
  "{r} reps is heavy for {lo}–{hi}. Use about {w2} kg next set.": "{r} عدات ثقيل على {lo}–{hi}. استخدم حوالي {w2} كجم الجولة الجاية.",
  "Move {x} up": "انقل {x} لفوق",
