  "Strong finish: {w} kg × {r}. Next time start your sets at {w2} kg.": "ختام قوي: {w} كجم × {r}. المرة الجاية ابدأ جولاتك بـ {w2} كجم.",
  "Harassment or bullying": "تحرش أو تنمر",
