  "You’ll stop being friends, and neither of you can find or add the other. You can unblock in Friends privacy.": "بتنتهي الصداقة، ولا أحد منكم يقدر يلقى الثاني أو يضيفه. تقدر تفك الحظر من خصوصية الأصدقاء.",
