  "What people reported. Check the person, then close the report. Many reports about one person is a sign to act.": "البلاغات اللي وصلت. شيّك على الشخص بعدين سكّر البلاغ. إذا فيه بلاغات كثيرة على نفس الشخص، لازم تتصرف.",
