  "Open again": "افتحه مرة ثانية",
  "User reports": "بلاغات المستخدمين",
  "Not handled": "ما انحلت",
  "Handled": "انحلت",
  "Adro reads and tracks your results to guide your training and food. It doesn’t diagnose or treat anything. Talk to your doctor about your results. Not medical advice.": "Adro يقرأ نتايجك ويتابعها عشان يوجه تمرينك وأكلك. ما يشخّص ولا يعالج أي شي. ناقش نتايجك مع طبيبك. هذا مو نصيحة طبية.",
  "Apple Health and Health Connect": "Apple Health و Health Connect",
  "If you connect them, Adro reads only what you allow (like steps, sleep, heart rate, weight and workouts) to show it in the app and adjust your plan. This data is never sold, never used for ads or marketing, and never shared with anyone else, including friends.": "إذا ربطتها، Adro يقرأ بس اللي تسمح فيه (مثل الخطوات والنوم ونبض القلب والوزن والتمارين) عشان يعرضه في التطبيق ويعدل خطتك. هالبيانات ما تنباع أبد، وما تُستخدم للإعلانات أو التسويق، وما تنشارك مع أي أحد، حتى الأصدقاء.",
  "How long we keep it": "كم نحتفظ فيها",
  "Your data stays while you have an account. When you delete your account, your data, photos and files are deleted from our servers.": "بياناتك تبقى دام عندك حساب. إذا حذفت حسابك، تنحذف بياناتك وصورك وملفاتك من سيرفراتنا.",
  "Updated": "آخر تحديث",
  "This policy was last updated on 18 October 2026.": "آخر تحديث لهالسياسة كان 18 أكتوبر 2026.",
  "No abuse": "ممنوع الإساءة",
  "There is zero tolerance for harassment, hate, nudity, spam or other objectionable content or behaviour. You can report or block anyone. Our team reviews reports within 24 hours and removes content and accounts that break these rules.": "ما نقبل أبد التحرش أو الكراهية أو العري أو الإزعاج أو أي محتوى أو تصرف مسيء. تقدر تبلّغ عن أي أحد أو تحظره. فريقنا يراجع البلاغات خلال 24 ساعة، ويشيل المحتوى والحسابات اللي تخالف هالقواعد.",
  "Rings and bands": "الخواتم والأساور",
  "{n} connected. Your last month is in.": "تم ربط {n}. بيانات آخر شهر وصلت.",
  "{n} wasn’t connected: access was not allowed.": "ما انربط {n}: ما تم السماح بالوصول.",
  "That took too long. Tap {n} to try again.": "طوّل كثير. اضغط {n} وجرب مرة ثانية.",
  "Couldn’t connect {n}. Please try again.": "ما قدرنا نربط {n}. جرب مرة ثانية.",
  "Sign in to {n} again to keep syncing.": "سجّل دخول {n} مرة ثانية عشان تستمر المزامنة.",
  "Couldn’t sync {n}. Please try again.": "ما قدرنا نزامن {n}. جرب مرة ثانية.",
  "{n} is almost ready. It opens as soon as Adro’s {n} account is approved.": "{n} قريب يجهز. يفتح أول ما ينقبل حساب Adro عند {n}.",
  "Connected. Synced {t}. Tap to sync now.": "مربوط. آخر مزامنة {t}. اضغط عشان تزامن الحين.",
  "Sign in again to keep syncing.": "سجّل دخول مرة ثانية عشان تستمر المزامنة.",
  "Sign in": "تسجيل الدخول",
  "{n} disconnected. Its data was deleted from Adro.": "تم فصل {n}. وانحذفت بياناته من Adro.",
  "Recovery, strain, sleep and HRV": "الاستشفاء والمجهود والنوم وتقلب النبض",
  "Readiness, sleep, HRV and activity": "الجاهزية والنوم وتقلب النبض والنشاط",
  "Heart rate, training and sleep": "النبض والتمرين والنوم",
  "Steps, sleep and heart rate": "الخطوات والنوم والنبض",
  "Connections": "الربط",
  "Devices, apps and your health records": "الأجهزة والتطبيقات وسجلاتك الصحية",
  "Some things connect straight to Adro. Everything else comes in through Apple Health or Health Connect. Here is both, and how to set each one up.": "بعض الأجهزة تنربط مباشرة مع Adro، والباقي يوصل عن طريق Apple Health أو Health Connect. هنا تلقى الاثنين، وكيف تربط كل واحد.",
  "Search connections": "دوّر على جهاز أو تطبيق",
  "Connects straight to Adro": "تنربط مباشرة مع Adro",
  "Sign in again": "سجّل دخول من جديد",
  "{n} is coming soon. Until then, it reaches Adro through {h}.": "{n} قريباً. لين ذاك الوقت، بياناته توصل Adro عن طريق {h}.",
  "More direct connections are coming soon.": "ربط مباشر لأجهزة أكثر قريباً.",
  "Everything else already works": "والباقي يشتغل من الحين",
  "Most watches, rings, scales and fitness apps reach Adro through {h}. Yours is almost surely one of them.": "أغلب الساعات والخواتم والموازين وتطبيقات الرياضة توصل Adro عن طريق {h}. وغالباً جهازك واحد منها.",
  "Connected. Your readings come in by themselves.": "مربوط. قراءاتك توصل لحالها.",
  "Connect to bring in your health data": "اربطه عشان توصل بياناتك الصحية",
  "Your device": "جهازك",
