  "Asks you to check your water every 2 hours": "يذكرك تشيك على مايك كل ساعتين",
  "Play a sound": "شغّل صوت",
  "Uses your phone’s notification sound": "يستخدم صوت التنبيهات في جوالك",
  "Rest timer sound": "صوت مؤقت الراحة",
  "Tap a type to choose how often it reminds you and whether it plays a sound. If you don’t hear sounds, turn off your phone’s silent mode.": "اضغط على أي نوع عشان تختار كل كم يذكرك وإذا يشغّل صوت. إذا ما تسمع الأصوات، طفّ الوضع الصامت في جوالك.",
  "Notifications are off in your phone settings": "التنبيهات مقفلة من إعدادات جوالك",
  "Your reminders won’t show until you allow notifications for Adro.": "تذكيراتك ما راح تطلع لين تسمح بالتنبيهات لـ Adro.",
  "Open phone settings": "افتح إعدادات الجوال",
  "Log out / Use another account": "تسجيل خروج / استخدم حساب ثاني",
  "Your account was made with this username. You can change it later in Account.": "حسابك انسوى بهذا اسم المستخدم. تقدر تغيّره بعدين من الحساب.",
  "We already sent a code here. Tap Next to enter it or get a new one.": "أرسلنا رمز لهذا الإيميل. اضغط التالي عشان تكتبه أو تطلب واحد جديد.",
  "We already sent a link here. Tap Next to check it or get a new one.": "أرسلنا رابط لهذا الإيميل. اضغط التالي عشان تتأكد منه أو تطلب واحد جديد.",
  "Use a different email": "استخدم إيميل ثاني",
  "By continuing you agree to the": "بالمتابعة توافق على",
  "Terms": "الشروط",
  "Privacy Policy": "سياسة الخصوصية",
  "You need to be 16 to 100 years old.": "لازم يكون عمرك من 16 إلى 100 سنة.",
  "That username is taken. Try another one.": "اسم المستخدم هذا مأخوذ. جرّب واحد ثاني.",
  "Coach (not approved)": "مدرب (ما انقبل)",
  "See your application": "شوف طلبك",
  "Couldn’t get all your data. Check your connection and try again.": "ما قدرنا نجيب كل بياناتك. تأكد من الاتصال وجرّب مرة ثانية.",
  "Sharing isn’t available on this phone.": "المشاركة مو متوفرة في هذا الجوال.",
  "Couldn’t save the file. Please try again.": "ما قدرنا نحفظ الملف. جرّب مرة ثانية.",
  "You’re offline. What you change is saved and syncs when you’re back online.": "أنت بدون إنترنت. اللي تغيّره ينحفظ ويتزامن لما يرجع الاتصال.",
  "{n} friends joined with your code. 1 month of Adro+ is saved for when it launches.": "{n} من أصحابك سجلوا بكودك. شهر من Adro+ محفوظ لك لين يطلق.",
  "Enter a valid email, like name@example.com.": "اكتب إيميل صحيح، مثل name@example.com.",
  "Lats": "المجنص",
  "Abs": "البطن",
