  "1 set isn’t done yet. Only the sets you finished are saved.": "باقي جولة وحدة ما خلصت. بس الجولات اللي خلصتها تنحفظ.",
  "{n} sets aren’t done yet. Only the sets you finished are saved.": "باقي {n} جولات ما خلصت. بس الجولات اللي خلصتها تنحفظ.",
  "Finish and save": "أنهِ واحفظ",
  "Discard this workout?": "تبي تحذف هالتمرين؟",
  "Nothing from it is saved. This can’t be undone.": "ما راح ينحفظ منه شي، وما تقدر ترجعه.",
  "This group workout is already saved": "هالتمرين الجماعي محفوظ من قبل",
  "Rest done": "خلصت الراحة",
  "Start another workout": "ابدأ تمرين ثاني",
  "Train anyway, this week only": "تمرّن على أي حال، هالأسبوع بس",
  "{w} added to {day} this week": "انضاف {w} ليوم {day} هالأسبوع",
  "Pregnant · week {n}": "حامل · الأسبوع {n}",
  "After birth · week {n}": "بعد الولادة · الأسبوع {n}",
  "Locked. Tap to open.": "مقفل. اضغط عشان تفتحه.",
  "Log {n} kg?": "نسجل {n} كجم؟",
  "That’s more than 10% away from your last weigh-in ({n} kg). Check the number and the unit.": "هذا يفرق أكثر من 10% عن آخر وزن سجلته ({n} كجم). تأكد من الرقم والوحدة.",
  "Don’t log": "لا تسجل",
  "Your weight is steady: {n} kg since the week of {d}. Right where you want it.": "وزنك ثابت: {n} كجم من أسبوع {d}. بالضبط مثل ما تبي.",
  "Your weight moved {n} kg since the week of {d}. If it keeps going that way, I’ll suggest adjusting calories.": "وزنك تغير {n} كجم من أسبوع {d}. إذا استمر كذا، بقترح عليك تعديل السعرات.",
  "You’re on track. {n} kg since the week of {d}. If your weight stays flat for two weeks, I’ll suggest adjusting calories.": "أنت ماشي صح. {n} كجم من أسبوع {d}. إذا ثبت وزنك أسبوعين، بقترح عليك تعديل السعرات.",
  "Your weight is going the other way ({n} kg since the week of {d}, comparing weekly averages). Weigh in a few more mornings.": "وزنك رايح بالاتجاه الثاني ({n} كجم من أسبوع {d}، بمقارنة متوسط كل أسبوع). وزن نفسك كم صباح زيادة.",
  "Ranges are the ones printed on your report. When it has none, the standard range for your sex and age is used and marked “Guideline”.": "المعدلات هي المطبوعة في تقريرك. إذا ما فيه معدل، نستخدم المعدل المعتاد لجنسك وعمرك ونكتب جنبه «إرشادي».",
  "Guideline: {r} {u}": "إرشادي: {r} {u}",
  "Under 60%: I suggest a lighter workout, and under 40% rest or very light. 80% or more: you’re ready to push.": "تحت 60%: أقترح تمرين أخف، وتحت 40% راحة أو خفيف جدًا. 80% أو أكثر: جاهز تضغط.",
  "80% or more is ready to train hard": "80% أو أكثر يعني جاهز للتمرين القوي",
  "Your goal: {n} steps a day": "هدفك: {n} خطوة في اليوم",
  "W{n}": "أ{n}",
  "About −{x} kg a week for you (your calorie floor)": "تقريبًا −{x} كجم في الأسبوع لك (حدّك الأدنى للسعرات)",
  "Close to maintenance for you (your calorie floor)": "قريب من سعرات الثبات لك (حدّك الأدنى للسعرات)",
  "Your calories can’t go lower than {n} kcal, so expect about {x} kg a week, not the usual range.": "سعراتك ما تنزل عن {n} سعرة، فتوقّع تقريبًا {x} كجم في الأسبوع، مو المعدل المعتاد.",
  "Your calories can’t go lower than {n} kcal, which is about your maintenance. Moving more is the way to lose weight.": "سعراتك ما تنزل عن {n} سعرة، وهذا تقريبًا سعرات الثبات حقتك. الحركة أكثر هي طريقك لنزول الوزن.",
  "Added “{name}”. Careful: it may contain {x}, which you’re allergic to.": "انضافت «{name}». انتبه: ممكن فيها {x}، وعندك حساسية منها.",
  "Allergens unknown: we don’t have this product’s ingredients. Check the label before you eat it.": "مسببات الحساسية مو معروفة: ما عندنا مكونات هالمنتج. شيّك على الملصق قبل لا تاكله.",
  "Allergies:": "الحساسية:",
  "Breastfeeding": "الرضاعة",
  "Client is allergic: {x}": "العميل عنده حساسية: {x}",
  "Contains {x}": "فيه {x}",
  "Couldn’t load your food. Check your connection and try again.": "ما قدرنا نحمّل أكلك. تأكد من الاتصال وحاول مرة ثانية.",
  "Some of your food didn’t load. What you see may be out of date.": "جزء من بيانات أكلك ما تحمّل. اللي تشوفه ممكن مو محدّث.",
  "For the {n} {u} you logged": "للـ {n} {u} اللي سجلتها",
  "Goal done that day. Nice.": "خلّصت الهدف ذاك اليوم. حلو.",
  "Includes {n} ml extra for training, cardio, pregnancy or breastfeeding.": "يشمل {n} مل زيادة للتمرين أو الكارديو أو الحمل أو الرضاعة.",
  "Log anyway": "سجّلها على كل حال",
  "No calorie deficit while you’re pregnant. In the first trimester you don’t need extra calories yet. Caffeine is kept to 200 mg a day.": "ما فيه نقص سعرات وانتي حامل. في أول ثلاث شهور ما تحتاجين سعرات زيادة للحين. الكافيين بحدود 200 ملغ في اليوم.",
  "No calorie deficit while you’re pregnant. Your goal includes about {n} kcal extra, and caffeine is kept to 200 mg a day.": "ما فيه نقص سعرات وانتي حامل. هدفك فيه تقريبًا {n} سعرة زيادة، والكافيين بحدود 200 ملغ في اليوم.",
  "Pregnancy mode is on: no calorie deficit, and about {x} kcal extra for this stage. Your daily goal in Food is {n} kcal. Caffeine: up to 200 mg a day.": "وضع الحمل شغّال: ما فيه نقص سعرات، وتقريبًا {x} سعرة زيادة لهالمرحلة. هدفك اليومي في الأكل {n} سعرة. الكافيين: لين 200 ملغ في اليوم.",
  "Your goal includes about {n} kcal extra, and your water goal 700 ml more.": "هدفك فيه تقريبًا {n} سعرة زيادة، وهدف الماي 700 مل أكثر.",
  "These times are for {city}. If you live somewhere else, check your local iftar and suhoor times.": "هالأوقات لـ{city}. إذا ساكن بمكان ثاني، شيّك على أوقات الفطور والسحور عندك.",
  "Times for {city}.": "الأوقات لـ{city}.",
  "Times are worked out for the city you pick. Outside these cities, check your local times.": "الأوقات محسوبة للمدينة اللي تختارها. إذا برا هالمدن، شيّك على أوقاتك المحلية.",
