  "Only one result so far. Upload another report to see the trend.": "عندك نتيجة وحدة بس. ارفع تحليل ثاني عشان تشوف التغيّر.",
  "Same as {d}": "نفس نتيجة {d}",
  "Up {n} since {d}": "زادت {n} من {d}",
  "Down {n} since {d}": "نزلت {n} من {d}",
  "This result isn’t a number, so it can’t be shown as a chart.": "هالنتيجة مو رقم، فما نقدر نعرضها كرسم.",
  "Talk to your doctor about your results. Not medical advice.": "كلّم دكتورك عن نتايجك. هذي مو نصيحة طبية.",
  "Your iron was low on your last test. Add red meat, lentils or spinach, with some vitamin C like orange or peppers. Check with your doctor.": "الحديد كان ناقص في آخر تحليل. زِد اللحم الأحمر أو العدس أو السبانخ، ومعها شي فيه فيتامين سي مثل البرتقال أو الفلفل. راجع دكتورك.",
  "Your iron was low on your last test. Add lentils, chickpeas or spinach, with some vitamin C like orange or peppers. Check with your doctor.": "الحديد كان ناقص في آخر تحليل. زِد العدس أو الحمص أو السبانخ، ومعها شي فيه فيتامين سي مثل البرتقال أو الفلفل. راجع دكتورك.",
  "Your vitamin D was low on your last test. Eggs, salmon and sardines help, and a bit of sun. Check with your doctor.": "فيتامين د كان ناقص في آخر تحليل. البيض والسلمون والسردين تفيد، وشوي شمس. راجع دكتورك.",
  "Your vitamin D was low on your last test. A bit of sun and mushrooms help. Check with your doctor.": "فيتامين د كان ناقص في آخر تحليل. شوي شمس والفطر تفيد. راجع دكتورك.",
  "Your B12 was low on your last test. Eggs, fish, meat and dairy have it. Check with your doctor.": "فيتامين ب١٢ كان ناقص في آخر تحليل. تلقاه في البيض والسمك واللحم والألبان. راجع دكتورك.",
  "Your B12 was low on your last test. Meat and chicken have it. Check with your doctor.": "فيتامين ب١٢ كان ناقص في آخر تحليل. تلقاه في اللحم والدجاج. راجع دكتورك.",
  "Your folate was low on your last test. Add leafy greens, beans and lentils. Check with your doctor.": "الفولات كان ناقص في آخر تحليل. زِد الورقيات والفاصوليا والعدس. راجع دكتورك.",
  "Your calcium was low on your last test. Laban, yogurt and cheese help. Check with your doctor.": "الكالسيوم كان ناقص في آخر تحليل. اللبن والزبادي والجبن تفيد. راجع دكتورك.",
  "Your calcium was low on your last test. Sardines, almonds and tahini help. Check with your doctor.": "الكالسيوم كان ناقص في آخر تحليل. السردين واللوز والطحينة تفيد. راجع دكتورك.",
  "Your magnesium was low on your last test. Nuts, seeds, beans and dates help. Check with your doctor.": "المغنيسيوم كان ناقص في آخر تحليل. المكسرات والبذور والفاصوليا والتمر تفيد. راجع دكتورك.",
  "Your magnesium was low on your last test. Beans, dates and oats help. Check with your doctor.": "المغنيسيوم كان ناقص في آخر تحليل. الفاصوليا والتمر والشوفان تفيد. راجع دكتورك.",
  "Taking iron? Have it with some vitamin C, away from tea, coffee and milk.": "تاخذ حديد؟ خذه مع شي فيه فيتامين سي، وبعيد عن الشاي والقهوة والحليب.",
  "Taking vitamin D? Have it with a meal that has some fat.": "تاخذ فيتامين د؟ خذه مع وجبة فيها شوي دهون.",
  "Taking creatine? Drink a bit more water through the day.": "تاخذ كرياتين؟ اشرب موية أكثر شوي خلال اليوم.",
  "That coach code doesn’t work anymore. Ask your coach for a new one.": "رمز المدرب هذا ما عاد يشتغل. اطلب من مدربك رمز جديد.",
  "This invite link doesn’t work": "رابط الدعوة هذا ما يشتغل",
  "Ask the person who sent it for a new link, or type their code in Adro.": "اطلب رابط جديد من اللي أرسله، أو اكتب رمزه في Adro.",
